use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fmt::Write,fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/batch-off-code-audit";const P:&str="/home/ubuntu/src/zopro-perf-work/batch-local-steal";const Z:&str="/home/ubuntu/src/zk-tools/zopro";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-27-batch-off-code-audit";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn main(){let r=Path::new(R);let d=Path::new(D);let a=read(r.join("analysis.json"));assert_eq!(a["selected_function_count"],16);assert_eq!(a["normalized_instruction_changes"],3);assert_eq!(a["changed_readonly_loads"],0);assert_eq!(a["unresolved_direct_control_references"],3);let m=read(format!("{Z}/docs/benchmarks/2026-10-27-clean-fft-adoption/artifacts/production-source-manifest.json"));for(f,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new(Z).join(f)),h.as_str().unwrap())}assert_eq!(m["source_files_sha256"].as_object().unwrap().len(),172);
 assert_eq!(hash(r.join("elf.rs")),hash(format!("{Z}/docs/benchmarks/2026-10-27-control-build-audit/artifacts/sections.rs")));let mut resolutions=Vec::new();let mut instructions=0;let mut readonly=0;for f in a["functions"].as_array().unwrap(){assert_eq!(f["control_bytes"],f["candidate_bytes"]);assert_eq!(f["instruction_offsets_equal"],true);assert_eq!(f["control_instructions"],f["candidate_instructions"]);instructions+=f["control_instructions"].as_u64().unwrap();readonly+=f["readonly_loads"].as_u64().unwrap();for change in f["normalized_changes"].as_array().unwrap(){for role in ["control","candidate"]{let asm=change[role].as_str().unwrap();assert!(asm.trim().ends_with("<_Unwind_Resume@plt>"));let address=u64::from_str_radix(asm.split_whitespace().nth(1).unwrap(),16).unwrap();assert!(fs::read_to_string(r.join(format!("{role}-plt.txt"))).unwrap().contains(&format!("{address:016x} <_Unwind_Resume@plt>:")));}resolutions.push(json!({"function":f["name"],"offset":change["offset"],"control":change["control"],"candidate":change["candidate"],"resolution":"both direct targets name _Unwind_Resume@plt; separately decoded PLT confirms symbol; dynamic binding not proven"}));}}assert_eq!(instructions,62887);assert_eq!(readonly,747);assert_eq!(resolutions.len(),3);save(r.join("unwind-PLT-resolutions.json"),&json!(resolutions));
 let mut libraries=BTreeMap::new();let ca=read(format!("{P}/native/control/artifacts.json"));let cb=read(format!("{P}/native/candidate/artifacts.json"));for(name,path)in ca["libraries"].as_object().unwrap(){let other=cb["libraries"][name].as_str().unwrap();let path=path.as_str().unwrap();libraries.insert(name,json!({"control":path,"candidate":other,"control_sha256":hash(path),"candidate_sha256":hash(other),"byte_equal":hash(path)==hash(other)}));}save(r.join("direct-library-comparison.json"),&json!(libraries));
 let mut pins=BTreeMap::new();for(role,artifacts)in [("control",&ca),("candidate",&cb)]{let bin=artifacts["binary"].as_str().unwrap();assert_eq!(hash(bin),artifacts["binary_sha256"].as_str().unwrap());pins.insert(bin.to_owned(),hash(bin));for(f,h)in artifacts["input_pins"].as_object().unwrap(){assert_eq!(hash(f),h.as_str().unwrap());pins.insert(f.clone(),hash(f));}pins.insert(format!("{P}/native/{role}/artifacts.json"),hash(format!("{P}/native/{role}/artifacts.json")));}pins.insert(format!("{P}/analysis.json"),hash(format!("{P}/analysis.json")));let mut raw=BTreeMap::new();let mut index=BTreeMap::new();fs::create_dir_all(d.join("artifacts")).unwrap();for e in fs::read_dir(r).unwrap(){let e=e.unwrap();let p=e.path();let name=e.file_name().to_string_lossy().to_string();if !e.file_type().unwrap().is_file(){continue}if name.ends_with(".asm"){raw.insert(name,hash(&p));continue}if !["rs","json","md","log","txt"].contains(&p.extension().and_then(|s|s.to_str()).unwrap_or("")){continue}let dest=d.join("artifacts").join(&name);fs::copy(&p,&dest).unwrap();assert_eq!(hash(&p),hash(&dest));index.insert(name,hash(dest));}save(d.join("artifacts/binary-library-pins.json"),&json!(pins));index.insert("binary-library-pins.json".into(),hash(d.join("artifacts/binary-library-pins.json")));save(d.join("artifacts/raw-local-only-sha256.json"),&json!(raw));index.insert("raw-local-only-sha256.json".into(),hash(d.join("artifacts/raw-local-only-sha256.json")));let close=json!({"status":"complete offline audit","production_changed":false,"adopted":false,"goal_achieved":false,"all8_CPU10x_rows":0,"SDK_requests":0,"Gnark_exports":0,"proof_ledger_unchanged":12518,"new_observer_tests":5,"inherited_ELF_reader_test_not_rerun":1,"owned_live_jobs":[],"owned_cloud_resources":[]});save(d.join("artifacts/closeout.json"),&close);index.insert("closeout.json".into(),hash(d.join("artifacts/closeout.json")));
 let mut md=String::from("# Arithmetic audit of the disabled scheduler build\n\nThe arithmetic comparison finds no changed instructions in the selected hot kernels after accounting for relocated references. **16 function instances contain 62,887 decoded instructions and 747 explicit readonly literal loads.** Instruction positions, sizes, mnemonics, registers, stack offsets, immediates and local branch targets agree; all checked literal payloads agree. Three remaining raw target differences are calls to `_Unwind_Resume@plt`, confirmed by separately decoded PLT entries.\n\nThis rules out changed lowering of those selected arithmetic bodies as an explanation. It does **not explain the 8.11% disabled-path slowdown**, prove whole-program equivalence, or resolve the failed control calibration. The preceding [batch-transfer screen](../2026-10-27-batch-local-steal/README.md) remains rejected: primary32 ON/OFF is 2.18% slower with 0/7 wins. Production and accepted latency remain unchanged. The original all-eight CPU 10× goal remains unmet, 0/8.\n\n## Scope\n\nThe exact accepted control is `14da8231f5797db25d3f45e3570a73c38141bfb957295d2548b0e457676e612a`; the candidate used OFF/ON is `fde4038c7106968518666299f422911abaf5f1408e84c9c006d2de28201e5ab3`. Both executables, actual direct libraries and recorded features are checked. Their linked arithmetic has equal native feature sets. The 172 production source hashes remain unchanged. No prover build, request, performance capture or Gnark verification is repeated in this audit; the proof ledger remains 12,518.\n\nSymbols are matched by demangled name and address-order occurrence for duplicates. Every instantiated symbol in the declared G1 streaming, G2 prefix, G1/G2 tree, Fq inverse, vector inverse and borrowed-window method families is checked. Direct control targets normalize to same-function byte offsets or named symbols with occurrence indices. RIP-relative displacements normalize separately from checking explicit-width `.rodata` payloads. Non-RIP register and memory operands remain significant. This is not a comparison of every function, indirect pointer binding, runtime relocation, input distribution, allocation address, cache behavior, frequency or scheduling. Static agreement cannot identify removable time.\n\n|Function family|Instances|Decoded instructions|\n|---|---:|---:|\n");let mut grouped=BTreeMap::<String,(usize,u64)>::new();for f in a["functions"].as_array().unwrap(){let name=f["name"].as_str().unwrap();let family=if name.contains("stream_g1_impl"){"G1 streaming"}else if name.contains("g2_prefix"){"G2 prefix"}else if name.contains("reduce_layer"){"G1/G2 affine trees"}else if name.contains("FqBatch"){"Vector inverse"}else if name.contains("borrowed_pending"){"Borrowed-window methods"}else{"Scalar Fq inverse"};let e=grouped.entry(family.into()).or_default();e.0+=1;e.1+=f["control_instructions"].as_u64().unwrap();}for(name,(count,n))in grouped{writeln!(md,"|{name}|{count}|{n}|").unwrap();}
 md.push_str("\n[Per-function comparison](artifacts/analysis.json), [RIP references](artifacts/RIP-references.json), [PLT resolutions](artifacts/unwind-PLT-resolutions.json), and [direct library hashes](artifacts/direct-library-comparison.json) retain the evidence. Raw disassemblies are local with hashes. They were decoded from the existing binaries without executing them.\n\nFive new observer tests pass across two invocations. They cover duplicate names and names with spaces, relative branches and named calls, preservation of register/stack/immediate changes, RIP widths/offsets and selecting borrowed-window methods. The unchanged ELF section reader and its existing test are inherited, not rerun. The first selection audit stopped because the borrowed-window matcher omitted its leading `<`; original source/log are retained. That selector alone was repaired and one targeted test added; four already successful normalization tests were not repeated. The audit then completed.\n\n## Next diagnostic\n\nDo not infer a new arithmetic rewrite, layout sweep or unchanged batch-steal retry from this result. A separately declared IBS demand-load diagnostic comparing these exact control and OFF executables could test whether load-source/latency behavior changed in the G2 prefix kernel. The [older IBS study](../2026-10-23-local-ibs-memory/README.md) used different source/binaries and does not answer this comparison. No such new capture occurs here. Memory metadata would still not prove a causal speedup, bandwidth saturation or insufficient RAM. A new optimization needs a distinct mechanism supported by measured whole-proof work.\n\n## Inherited CPU and Metal comparison\n\nThese are the accepted local observations against supplied historical M5 figures, not new timings from this audit. The [canonical all-shape report](../2026-10-27-clean-fft-adoption/README.md) retains its full-performance-gate failure and engineering exception.\n\n|Shape|Accepted ms|CPU reference ms|CPU/accepted|Metal reference ms|Metal/accepted|\n|---|---:|---:|---:|---:|---:|\n");let shapes=["1x2","2x2","4x2","8x2","12x2","16x2","24x2","merge-24x1"];let times=[8.324853,11.460675,15.854365,24.084626,33.693397,39.981636,66.010670,65.086624];let cpus=[37.,59.,109.,189.,284.,335.,528.,507.];let metals=[24.,30.,48.,74.,101.,124.,176.,175.];for i in 0..8{writeln!(md,"|{}|{:.6}|{:.0}|{:.3}×|{:.0}|{:.3}×|",shapes[i],times[i],cpus[i],cpus[i]/times[i],metals[i],metals[i]/times[i]).unwrap();}md.push_str("\nAccepted merge54 remains 161.341835 ms with no supplied M5 reference. The latest fresh primary control observation remains 8.358001 ms from the preceding screen. No AWS, portable, pressure, concurrency, phone, TEE, minimum-RAM or large-circuit qualification is added.\n\n[Design](artifacts/design.md), [observer tests](artifacts/tests.log), [additional selector test](artifacts/selector-test.log), [artifact hashes](artifact-index.json).\n");fs::write(d.join("README.md"),md).unwrap();save(d.join("artifact-index.json"),&json!(index));for(f,h)in &index{assert_eq!(hash(d.join("artifacts").join(f)),*h)}println!("Closed offline arithmetic audit:16functions62887instructions747readonlyloads;{}artifacthashes;zeroSDK;ledger12518",index.len());}
